struct usb_cdc_union_desc *get_cdc_union_descriptor(struct usb_interface *intf)
{
    struct usb_cdc_union_desc *desc;
    unsigned char *extra;
    int len;

    if (!intf || !intf->cur_altsetting || !intf->cur_altsetting->extra)
        return NULL;

    extra = intf->cur_altsetting->extra;
    len = intf->cur_altsetting->extralen;

    if (!extra || len <= 0) {
        pr_err("No extra descriptor data available.\n");
        return NULL;
    }

    while (len > 0) {
        if (len < sizeof(*desc)) {
            pr_err("Descriptor too short.\n");
            return NULL;
        }

        desc = (struct usb_cdc_union_desc *)extra;
        if (desc->bDescriptorType == USB_DT_CS_INTERFACE &&
            desc->bDescriptorSubtype == USB_CDC_UNION_TYPE) {
            return desc;
        }

        len -= desc->bLength;
        extra += desc->bLength;
    }

    pr_err("CDC union descriptor not found.\n");
    return NULL;
}

struct usb_cdc_union_desc *get_cdc_union_desc(struct usb_interface *intf) {
    struct usb_host_interface *alt;
    unsigned char *extra;
    int extralen;
    struct usb_cdc_union_desc *desc = NULL;

    alt = &intf->altsetting[0];
    extra = alt->extra;
    extralen = alt->extralen;

    if (!extra || extralen <= 0) {
        dev_dbg(&intf->dev, "No extra descriptor data found\n");
        return NULL;
    }

    while (extralen >= sizeof(struct usb_cdc_union_desc)) {
        desc = (struct usb_cdc_union_desc *)extra;
        if (desc->bDescriptorType == USB_DT_CS_INTERFACE &&
            desc->bDescriptorSubtype == USB_CDC_UNION_SUBTYPE) {
            break;
        }
        extralen -= desc->bLength;
        extra += desc->bLength;
        desc = NULL;
    }

    if (!desc) {
        dev_dbg(&intf->dev, "CDC union descriptor not found\n");
        return NULL;
    }

    if (desc->bLength < sizeof(struct usb_cdc_union_desc)) {
        dev_dbg(&intf->dev, "Invalid CDC union descriptor length\n");
        return NULL;
    }

    return desc;
}

struct usb_cdc_union_desc *get_cdc_union_desc(struct usb_interface *intf)
{
    struct usb_host_interface *host_intf;
    struct usb_cdc_union_desc *desc = NULL;
    unsigned char *extra;
    int len;

    if (!intf)
        return NULL;

    host_intf = &intf->altsetting[0];
    extra = host_intf->extra;
    len = host_intf->extralen;

    if (!extra || len <= 0) {
        dev_dbg(&intf->dev, "No extra descriptors found\n");
        return NULL;
    }

    while (len > 0) {
        unsigned int this_length = *extra;

        if (this_length == 0) {
            dev_dbg(&intf->dev, "Invalid descriptor length\n");
            return NULL;
        }

        if (len < this_length) {
            dev_dbg(&intf->dev, "Incomplete descriptor\n");
            return NULL;
        }

        if (extra[1] == USB_DT_CS_INTERFACE && extra[2] == USB_CDC_UNION_TYPE) {
            if (this_length >= sizeof(struct usb_cdc_union_desc))
                desc = (struct usb_cdc_union_desc *)extra;
            break;
        }

        len -= this_length;
        extra += this_length;
    }

    if (!desc)
        dev_dbg(&intf->dev, "CDC union descriptor not found\n");

    return desc;
}

struct usb_cdc_union_desc *get_cdc_union_desc(struct usb_interface *intf)
{
    struct usb_host_interface *host_intf;
    struct usb_cdc_union_desc *desc = NULL;
    int i;

    if (!intf)
        return NULL;

    host_intf = &intf->altsetting[0];
    if (!host_intf->extralen || !host_intf->extra)
        return NULL;

    for (i = 0; i < host_intf->extralen; ) {
        struct usb_descriptor_header *header = (struct usb_descriptor_header *)&host_intf->extra[i];
        if (header->bLength < sizeof(*header))
            return NULL;

        if (header->bDescriptorType == USB_DT_CS_INTERFACE) {
            if (host_intf->extralen - i >= sizeof(*desc)) {
                desc = (struct usb_cdc_union_desc *)&host_intf->extra[i];
                if (desc->bDescriptorSubtype == USB_CDC_UNION_SUBTYPE)
                    return desc;
            }
            break;
        }
        i += header->bLength;
    }

    return NULL;
}

struct usb_cdc_union_desc *get_cdc_union_desc(struct usb_interface *intf)
{
	struct usb_descriptor_header *header;
	struct usb_cdc_union_desc *desc = NULL;
	unsigned char *extra;
	int len;

	extra = intf->extra;
	len = intf->extralen;

	if (!extra || len <= 0)
		goto error;

	for (; len > 0; extra += header->bLength, len -= header->bLength) {
		header = (struct usb_descriptor_header *)extra;
		if (!header)
			break;

		if (header->bLength < sizeof(*desc))
			continue;

		if (header->bDescriptorType == USB_DT_CS_INTERFACE) {
			desc = (struct usb_cdc_union_desc *)header;
			if (desc->bDescriptorSubtype == USB_CDC_UNION_TYPE)
				break;
			else
				desc = NULL;
		}
	}

	if (!desc)
		goto error;

	return desc;

error:
	dev_err(&intf->dev, "CDC union descriptor not found\n");
	return NULL;
}
